/// Hub-primary, file-fallback composition for the agent messaging fabric
/// (issue #27 phase 1): the hub is the live transport, the file inboxes
/// remain the offline fallback. Both implementations stay behind the
/// existing [MessagingRepository] contract — the agent-loop seams
/// (`externalSteeringSource`, idle wake, `mailboxPrefix`) are untouched.
///
/// * `send` asks the primary whether it can deliver the recipient
///   ([RoutingMessagingRepository.resolveTarget]); a hub-shaped recipient
///   goes hub-ward, everything else (and every hub failure) lands in the
///   file fabric exactly as before. While the hub is down, file-bound mail
///   is tracked and FORWARDED on the next connected call (at-least-once;
///   the inbox probe and every send trigger the flush, so a reconnect
///   drains the queue within one probe tick).
/// * `peek`/`drain` merge the primary's inbox into [primaryMailbox]'s drain
///   only — the one fabric mailbox the hub identity owns. Subagent drains
///   never touch the hub, so a child cannot steal hub mail.
/// * `directory` merges both views; a file entry wins on id collision.
library;

import 'agent_message.dart';
import 'messaging_repository.dart';

/// Capability of a primary repository that routes by recipient: it can say
/// whether [toId] is deliverable through it and return the CANONICAL target
/// id (a display name resolved to the peer id, a channel passed through).
/// Null means "not mine" — the recipient belongs to the file fabric (or the
/// primary is not connected). Implementations must be cheap to call and
/// never throw for a null answer.
abstract interface class RoutingMessagingRepository {
  /// Whether the live transport is currently usable. A false answer routes
  /// everything to the fallback.
  bool get isConnected;

  /// The canonical target id for [toId] on this transport, or null when
  /// [toId] is not deliverable here (unknown recipient, transport down).
  Future<String?> resolveTarget(String toId);
}

/// A [MessagingRepository] composing a primary (hub) transport with a
/// fallback (file) fabric. See the library docs for the routing rules.
// ignore_for_file: prefer_initializing_formals
final class FallbackMessagingRepository
    implements MessagingRepository, RoutingMessagingRepository {
  FallbackMessagingRepository({
    required MessagingRepository primary,
    required MessagingRepository fallback,
  }) : _primary = primary,
       _fallback = fallback;
  final MessagingRepository _primary;
  final MessagingRepository _fallback;

  /// The fabric mailbox whose drain merges hub mail — the hub identity's
  /// own address (`<sessionId>/main`). The host wires it after construction
  /// (the mailbox prefix exists only once a session does). Null or a null
  /// answer = pure-file drains.
  String? Function()? primaryMailbox;

  /// Recipient -> message ids this repository queued into the file fabric
  /// while the hub path was unavailable, pending forward-on-reconnect.
  final _pendingForward = <String, Set<String>>{};

  /// The primary as a router, when it advertises the capability.
  RoutingMessagingRepository? get _router =>
      _primary is RoutingMessagingRepository
      ? _primary as RoutingMessagingRepository
      : null;

  /// The composite routes as its primary routes: connected only when the
  /// hub is, resolvable only for hub roster targets (or channels). This is
  /// what lets recipient guards consult the fabric without knowing DAP.
  @override
  bool get isConnected => _router?.isConnected ?? false;

  @override
  Future<String?> resolveTarget(String toId) => _safeResolve(toId);

  @override
  Future<void> send(AgentMessage message) async {
    await _flushQueued();
    final target = await _safeResolve(message.toId);
    if (target != null) {
      try {
        await _primary.send(_retarget(message, target));
        return;
      } on Object {
        // Hub delivery failed (whois race, evicted socket) — the file
        // fallback below keeps the message; the forwarder retries later.
      }
    } else if (message.toId.startsWith('#')) {
      // Channels exist only on the hub; a file mailbox nobody polls would
      // be a silent dead drop. Honest failure instead.
      throw StateError(
        'hub not connected — channel ${message.toId} is undeliverable',
      );
    }
    await _fallback.send(message);
    _trackForForward(message);
  }

  /// Rewrites [message]'s recipient to the resolved [target], keeping the
  /// identity (id) stable so recipients dedupe across retried deliveries.
  AgentMessage _retarget(AgentMessage message, String target) => AgentMessage(
    id: message.id,
    fromId: message.fromId,
    toId: target,
    text: message.text,
    sentAt: message.sentAt,
    hops: message.hops,
    kind: message.kind,
  );

  Future<String?> _safeResolve(String toId) async {
    final router = _router;
    if (router == null || !router.isConnected) return null;
    try {
      return await router.resolveTarget(toId);
    } on Object {
      return null;
    }
  }

  void _trackForForward(AgentMessage message) => _pendingForward
      .putIfAbsent(message.toId, () => <String>{})
      .add(message.id);

  /// Forwards file-queued hub mail on a live primary. Cheap no-op when
  /// nothing is tracked or the hub is down — and while the hub is down
  /// NOTHING is untracked: a disconnected resolve cannot tell "not a hub
  /// peer" from "not connected yet", so the queue survives until a
  /// connected call forwards it. Called opportunistically from every send
  /// and from `peek`/`drain` — the CLI's 2s inbox probe makes the
  /// post-reconnect flush immediate without any timer or stream wiring.
  Future<void> _flushQueued() async {
    final router = _router;
    if (_pendingForward.isEmpty) return;
    if (router == null || !router.isConnected) return;
    for (final entry in _pendingForward.entries.toList()) {
      final recipient = entry.key;
      final target = await _safeResolve(recipient);
      if (target == null) {
        // Connected, and the roster does not know this recipient: the file
        // fabric owns this mail — stop tracking, never forward it.
        _pendingForward.remove(recipient);
        continue;
      }
      final pending = await _safePeek(recipient);
      final ours = [
        for (final message in pending)
          if (entry.value.contains(message.id)) message,
      ];
      var forwarded = 0;
      for (final message in ours) {
        try {
          await _primary.send(_retarget(message, target));
          forwarded++;
        } on Object {
          break; // keep the rest queued; the next connected call retries
        }
      }
      if (forwarded == 0) continue;
      final forwardedIds = ours.take(forwarded).map((m) => m.id).toSet();
      await _removeFromFileInbox(recipient, forwardedIds);
      entry.value.removeAll(forwardedIds);
      if (entry.value.isEmpty) _pendingForward.remove(recipient);
    }
  }

  /// Removes the forwarded copies from the recipient's file inbox so a
  /// file-polling peer never sees the mail twice. Drain-and-rewrite: the
  /// message id is the file name, so survivors come back unchanged and in
  /// order. A crash between hub-send and removal duplicates the message —
  /// the drain merge dedupes (by id, and by sender+time+body for the hub's
  /// re-wrapped frames), so the peer sees it once (at-least-once).
  Future<void> _removeFromFileInbox(
    String recipient,
    Set<String> forwardedIds,
  ) async {
    try {
      final all = await _fallback.drain(recipient);
      for (final message in all) {
        if (!forwardedIds.contains(message.id)) await _fallback.send(message);
      }
    } on Object {
      // Best-effort cleanup; the copy left behind dedupes by id anyway.
    }
  }

  Future<List<AgentMessage>> _safePeek(String agentId) async {
    try {
      return await _fallback.peek(agentId);
    } on Object {
      return const [];
    }
  }

  /// Whether [agentId] is the hub identity's fabric mailbox (the one drain
  /// that merges hub mail).
  bool _isPrimaryMailbox(String agentId) =>
      primaryMailbox != null && primaryMailbox!() == agentId;

  @override
  Future<List<AgentMessage>> peek(String agentId) async {
    await _flushQueued();
    final fileMessages = await _safePeek(agentId);
    if (!_isPrimaryMailbox(agentId)) return fileMessages;
    final hubMessages = await _safeInbox(agentId, consume: false);
    return _merge(hubMessages, fileMessages);
  }

  @override
  Future<List<AgentMessage>> drain(String agentId) async {
    await _flushQueued();
    final fileMessages = await _fallback.drain(agentId);
    if (!_isPrimaryMailbox(agentId)) return fileMessages;
    final hubMessages = await _safeInbox(agentId, consume: true);
    return _merge(hubMessages, fileMessages);
  }

  /// The primary inbox, never throwing — the steering contract requires an
  /// empty-list answer over a broken transport.
  Future<List<AgentMessage>> _safeInbox(
    String agentId, {
    required bool consume,
  }) async {
    try {
      return consume
          ? await _primary.drain(agentId)
          : await _primary.peek(agentId);
    } on Object {
      return const [];
    }
  }

  /// Oldest-first merge of both transports' inboxes. Dedup on two keys:
  /// the message id (stable across retried deliveries), and — because the
  /// hub wire assigns each frame a FRESH id per delivery — the
  /// sender+timestamp+body tuple, so a re-wrapped or redelivered hub frame
  /// still collapses onto its stable-id copy (at-least-once forwarding).
  List<AgentMessage> _merge(
    List<AgentMessage> hubMessages,
    List<AgentMessage> fileMessages,
  ) {
    final seen = <String>{};
    final seenBodies = <String>{};
    return [
      for (final message in [...hubMessages, ...fileMessages])
        if (seen.add(message.id) &&
            seenBodies.add(
              '${message.fromId}|${message.sentAt}|${message.text}',
            ))
          message,
    ]..sort((a, b) {
      final byTime = a.sentAt.compareTo(b.sentAt);
      return byTime != 0 ? byTime : a.id.compareTo(b.id);
    });
  }

  @override
  Future<void> register(
    String agentId, {
    String? sessionName,
    List<AgentCapability> capabilities = const [],
  }) async {
    await _fallback.register(
      agentId,
      sessionName: sessionName,
      capabilities: capabilities,
    );
    try {
      await _primary.register(
        agentId,
        sessionName: sessionName,
        capabilities: capabilities,
      );
    } on Object {
      // Best-effort: hub presence rides the signed hello, a failed
      // announce must not break session startup.
    }
  }

  @override
  Future<void> touch(String agentId, {bool busy = false}) async {
    await _fallback.touch(agentId, busy: busy);
    try {
      await _primary.touch(agentId, busy: busy);
    } on Object {
      // Best-effort heartbeat.
    }
  }

  @override
  Future<List<MailboxEntry>> directory() async {
    final entries = await _fallback.directory();
    try {
      final ids = {for (final entry in entries) entry.id};
      for (final entry in await _primary.directory()) {
        // File truth wins on collision: a local mailbox is drained locally.
        if (!ids.add(entry.id)) continue;
        entries.add(entry);
      }
    } on Object {
      // A broken primary hides only its own peers.
    }
    return entries;
  }
}

/// The hub as the messaging fabric's primary transport (issue #27 phase 1):
/// a [MessagingRepository] over the DAP hub client, composed with the file
/// fabric through `FallbackMessagingRepository`.
///
/// Lives in `bin/` on purpose — `package:fa_hub_client` pulls `dart:io`
/// (WebSocket, key files) and `lib/src/**` stays web-pure, exactly like the
/// `hub` plugin host in `fah_hub_plugin.dart`. The harness's pure
/// `RoutingMessagingRepository` capability is what lets the composition
/// route without knowing anything about DAP.
///
/// Mapping to the hub model:
/// * presence/registration ride the signed hello (`register`/`touch` are
///   deliberate no-ops — the display name is the DAP identity, stable
///   across restarts);
/// * `send` targets are resolved against the hub roster BEFORE the call
///   ([resolveTarget] — exact 16-hex id, unique display name, or `#channel`);
/// * inbound frames land in the package repository's in-memory inbox keyed
///   by OUR hub agent id, so `peek`/`drain` ignore the fabric agentId (the
///   composition guards that only the wired `primaryMailbox` reaches here);
/// * `directory` maps the hub roster (online AND offline — the hub keeps
///   offline mailboxes and flushes them on the peer's next connect) onto
///   mailbox entries.
library;

import 'package:fa_hub_client/fa_hub_client.dart' as hub;
import 'package:flutter_agent_harness/flutter_agent_harness.dart';

/// The hub-fabric gate (issue #304 E6, mirrors `images.registry: false`):
/// the CLI wires the hub as the fabric's primary transport only when the
/// `hub` plugin is enabled, DAP is unlocked (`DAP_MASTER_SECRET`) and the
/// `fabric.hub` kill switch is not off. With the switch off the fabric is
/// the bare file layer and `agent_directory` reproduces the legacy
/// listing byte-for-byte (REG).
bool hubFabricWired({
  required bool hubPluginEnabled,
  required bool dapUnlocked,
  required bool fabricHubAllowed,
}) => hubPluginEnabled && dapUnlocked && fabricHubAllowed;

/// Hub-backed [MessagingRepository] over a [hub.HubPlugin].
final class HubFabricRepository
    implements MessagingRepository, RoutingMessagingRepository {
  HubFabricRepository(this._plugin);

  final hub.HubPlugin _plugin;

  hub.HubMessagingRepository? get _repo => _plugin.repository;

  String? get _agentId => _plugin.agentId;

  @override
  bool get isConnected => _repo?.client.connected ?? false;

  @override
  Future<String?> resolveTarget(String toId) async {
    if (!isConnected) return null;
    // Channels are always hub-shaped (the package client routes the send
    // and auto-creates unknown channels on first use — except on
    // master-gated hubs (hub.fa1.dev), where joining an unknown channel
    // is access_denied and only a master connection creates channels).
    if (toId.startsWith('#')) return toId;
    final me = _agentId;
    if (me != null && toId == me) return null; // our own fabric mailbox
    // A hub drop mid-query fails the waiter ('connection closed') — fall
    // back to the file fabric instead of letting it escape (issue #988).
    final roster = await _presenceRoster();
    if (roster == null) return null;
    for (final agent in roster) {
      if (agent.agentId == toId) return toId; // exact id wins
    }
    final byName = roster.where((agent) => agent.name == toId).toList();
    // A display name resolves only when it is unambiguous — matches the
    // dap_dm resolver; an ambiguous name falls through to the file fabric
    // where the session-name resolution owns it.
    return byName.length == 1 ? byName.single.agentId : null;
  }

  /// The hub roster, or null when the query fails (drop mid-query,
  /// reconnect in flight) — callers fall back to the file fabric.
  Future<List<hub.AgentInfo>?> _presenceRoster() async {
    try {
      return await _repo!.client.presenceQuery();
    } on Object {
      return null;
    }
  }

  @override
  Future<void> send(AgentMessage message) async {
    final repo = _repo;
    final agentId = _agentId;
    if (repo == null || agentId == null) {
      throw StateError('hub fabric not connected — no hub client');
    }
    await repo.send(
      hub.AgentMessage(
        id: message.id,
        fromId: agentId,
        toId: message.toId,
        text: message.text,
        sentAt: message.sentAt,
      ),
    );
  }

  @override
  Future<List<AgentMessage>> peek(String agentId) async {
    final repo = _repo;
    final inbox = _agentId;
    if (repo == null || inbox == null) return const [];
    try {
      return _fromHub(await repo.peek(inbox));
    } on Object {
      return const [];
    }
  }

  @override
  Future<List<AgentMessage>> drain(String agentId) async {
    final repo = _repo;
    final inbox = _agentId;
    if (repo == null || inbox == null) return const [];
    try {
      return _fromHub(await repo.drain(inbox));
    } on Object {
      return const [];
    }
  }

  /// Maps the package's mirrored AgentMessage onto the harness type. The
  /// recipient is OUR hub inbox — reported as the hub agent id so the
  /// steering attribution reads the true sender.
  List<AgentMessage> _fromHub(List<hub.AgentMessage> messages) => [
    for (final message in messages)
      AgentMessage(
        id: message.id,
        fromId: message.fromId,
        toId: _agentId ?? message.toId,
        text: message.text,
        sentAt: message.sentAt,
        hops: message.hops,
      ),
  ];

  @override
  Future<void> register(
    String agentId, {
    String? sessionName,
    List<AgentCapability> capabilities = const [],
  }) async {
    // Presence rides the signed hello; the hub display name is the DAP
    // identity (stable across restarts), not the per-session fabric name.
    // Capabilities are not carried by the hub wire yet — the file fabric's
    // `.capabilities` marker is the discovery source (issue #27 phase 2).
  }

  @override
  Future<void> touch(String agentId, {bool busy = false}) async {
    // Hub liveness is the connection itself; the hub dates peers by their
    // last authenticated frame (lastSeen), not by client heartbeats. The
    // busy run-state is local knowledge (file marker) until the hub wire
    // carries presence states.
  }

  @override
  Future<List<MailboxEntry>> directory() async {
    final repo = _repo;
    if (repo == null) return const [];
    // Same guard as resolveTarget: a hub drop mid-query (the client fails
    // the waiter with StateError('connection closed')) must fall back to
    // the file fabric, never crash the caller (ffb6aa67b pattern).
    final roster = await _presenceRoster();
    if (roster == null) return const [];
    return [
      for (final agent in roster)
        MailboxEntry(
          id: agent.agentId,
          name: agent.name,
          lastActivity: agent.lastSeen,
          // Registration-backed presence: the hub knows who is connected —
          // no mtime heuristic.
          presence: agent.online ? AgentPresence.live : AgentPresence.offline,
          // Hub-sourced marker (issue #304 AC3): the directory renders the
          // `[hub]` tag so DAP peers read apart from file mailboxes.
          source: mailboxSourceHub,
        ),
    ];
  }
}

/// All inbound `msg` frames, oldest first.
Stream<InboundMessage> get inbound => _inbound.stream;

/// Every hub `error` frame received (unknown_agent, access_denied, …).
/// Hub rejections must never be silent — listeners surface them.
Stream<HubError> get errors => _errors.stream;

/// Every channel join the hub denied (issue #1016): channel, code and
/// msg — hosts render "not invited / wrong channel id" instead of a
/// silent absence. An explicit [join] retries (and clears) the mark.
Stream<JoinDenied> get joinDenials => _joinDenials.stream;

/// Fires after every accepted welcome (first connect and each
/// reconnect) — the restart-redelivery hook for pending invites.
Stream<void> get welcomeEvents => _welcomeEvents.stream;

/// True while a welcome was received on a currently open socket and the
/// client was not deliberately disconnected ([disconnect]). The
/// `!_closing` guard matters: dart:io can leave `readyState` at `open`
/// even after `close()` completed, so without it a post-disconnect
/// [status] would claim `connected: true`.
bool get connected =>
    !_closing &&
    _ws != null &&
    _ws!.readyState == WebSocket.open &&
    _firstWelcome.isCompleted;

/// Completes with our agent id after the first welcome.
Future<String> get welcomed => _firstWelcome.future;

/// Our hub agent id once the hub welcomed us.
String? agentId;

/// Request cap for whois/flush/presenceQuery (see [requestTimeout]).
static const defaultRequestTimeout = Duration(seconds: 10);

/// 1 s doubling, capped at 30 s (spec "Client reconnect").
static Duration defaultBackoff(int attempt) {
  // Clamp BEFORE shifting: `1 << (attempt - 1)` overflows 64-bit shift
  // semantics — attempt 64 is negative and attempt 65+ is ZERO, so the
  // `seconds > 30` cap never fired and the delay degenerated to
  // Duration.zero: a tight reconnect loop burning a full core forever
  // (observed live at _reconnectAttempt = 69,730,601).
  if (attempt >= 6) return const Duration(seconds: 30);
  return Duration(seconds: 1 << (attempt - 1));
}

/// Connects and keeps the connection alive until [disconnect]. Completes
/// after the first welcome; a later drop re-hellos (after backoff) and
/// flushes the offline mailbox again. A rejected hello completes this
/// future with [HubError].
bool _loopStarted = false;

Future<String> connect() {
  if (config.url == null) {
    return Future.error(StateError('hub config has no url'));
  }
  if (!_loopStarted) {
    _loopStarted = true;
    _closing = false;
    unawaited(_connectLoop(++_epoch));
  }
  return _firstWelcome.future;
}

Future<void> _connectLoop(int epoch) async {
  while (!_closing && epoch == _epoch) {
    var welcomed = false;
    try {
      welcomed = await _cycle(epoch);
    } on HubError catch (error) {
      // pre-welcome rejection (bad signature, …) — fatal, stop retrying
      if (!_firstWelcome.isCompleted) _firstWelcome.completeError(error);
      return;
    } on Object {
      // unexpected cycle failure — treat as unwelcomed cycle
    }
    if (_closing || epoch != _epoch) return;
    if (welcomed) _reconnectAttempt = 0;
    _reconnectAttempt++;
    await Future<void>.delayed(backoff(_reconnectAttempt));
  }
}

/// One connect → hello → welcome → flush → hold-until-close cycle.
/// Returns whether the hub welcomed us; only pre-welcome hub rejections
/// throw ([HubError]) — transport failures just return `false`.
Future<bool> _cycle(int epoch) async {
